@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito:wght@400;600;700;800;900&display=swap');
:root{--ink:#29464a;--muted:#779195;--mint:#daf0d4;--green:#4c9a69;--gold:#ffcf6a;--cream:#fffaf0;--line:#e7eee2;--shadow:0 18px 55px #35685c24}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#f5f8ee;color:var(--ink);font-family:Nunito,system-ui,sans-serif;display:flex;align-items:center;justify-content:center;padding:26px;background-image:radial-gradient(#b8d5be55 1px,transparent 1px);background-size:22px 22px}.game-shell{width:min(1180px,100%);background:var(--cream);border:1px solid #e7eddc;border-radius:22px;box-shadow:var(--shadow);overflow:hidden}.topbar{height:66px;display:flex;align-items:center;padding:0 26px;background:#fffdf7;border-bottom:1px solid #edf0e5;position:relative;z-index:2}.brand{display:flex;align-items:center;gap:9px;color:#294c4b;text-decoration:none;font-size:19px;font-weight:900;letter-spacing:-.7px}.brand-mark{width:30px;height:30px;display:grid;place-items:center;background:#e8f5d9;color:#55a06b;border-radius:10px;font-size:22px}.brand-light{font-weight:600;color:#76a894}.world-title{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;font:500 10px 'DM Mono',monospace;letter-spacing:1.2px;color:#62847d}.world-title i{font-style:normal;color:#b9c9b8}.live-dot{width:7px;height:7px;border-radius:50%;background:#79bd78;box-shadow:0 0 0 3px #79bd7828}.top-actions{margin-left:auto;display:flex;align-items:center;gap:9px}.icon-btn,.avatar-mini{width:34px;height:34px;border:1px solid #e7eddf;background:#fff;border-radius:11px;color:#557a75;font-size:16px;cursor:pointer}.icon-btn:hover,.avatar-mini:hover{background:#edf6e9}.avatar-mini{background:#eff8dd;border:0;font-size:18px}.game-frame{height:min(68vh,590px);min-height:390px;position:relative;overflow:hidden;background:#9bd9e9;touch-action:none}canvas{width:100%;height:100%;display:block;image-rendering:pixelated}.world-overlay{position:absolute;inset:0;pointer-events:none}.quest-card{position:absolute;left:19px;top:18px;display:flex;align-items:center;gap:10px;padding:9px 13px 9px 9px;border-radius:13px;background:#fffaf0eF;box-shadow:0 5px 20px #316a5820;min-width:220px}.quest-icon{width:31px;height:31px;display:grid;place-items:center;border-radius:10px;background:#ffedc5;color:#d69335;font-size:18px}.quest-card small,.quest-card strong{display:block}.quest-card small{font:500 8px 'DM Mono',monospace;letter-spacing:.8px;color:#9a9c7e}.quest-card strong{font-size:11px;color:#455f54;margin-top:2px}.quest-progress{margin-left:auto;background:#e7f2dc;color:#599462;font:500 9px 'DM Mono',monospace;padding:5px 7px;border-radius:7px}.world-badge{position:absolute;right:18px;top:18px;display:flex;align-items:center;gap:8px;padding:7px 11px;background:#fffcf0dc;border-radius:12px;box-shadow:0 5px 18px #3a695315}.world-badge>span{font-size:21px}.world-badge b,.world-badge small{display:block}.world-badge b{font-size:10px}.world-badge small{font-size:9px;color:#89a29a}.controls-hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);padding:7px 12px;border-radius:9px;background:#fffaf0d9;color:#728b82;font-size:10px;white-space:nowrap;box-shadow:0 3px 14px #316a5814}.controls-hint kbd{font:500 9px 'DM Mono',monospace;color:#547c6c;border:1px solid #d5e2d4;border-radius:4px;padding:2px 4px;background:white;margin-right:2px}.controls-hint span{margin:0 5px;color:#b1c2b5}.toast{position:absolute;left:50%;top:70px;transform:translate(-50%,-10px);opacity:0;background:#315a4beF;color:#fff;padding:9px 15px;border-radius:10px;font-size:12px;box-shadow:0 6px 20px #315a4b30;transition:.25s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.inventory-bar{min-height:91px;display:flex;align-items:center;padding:12px 20px;gap:14px;background:#fffdf7;border-top:1px solid #e9eee2}.inventory-label{display:flex;align-items:center;gap:8px;color:#95a69a;font:500 8px 'DM Mono',monospace;letter-spacing:.7px;line-height:1.5;min-width:94px}.inventory-label b{color:#577a70}.bag-icon{height:33px;width:33px;border-radius:10px;background:#eaf3df;color:#66a073;display:grid;place-items:center;font-size:21px}.slots{display:flex;gap:7px;flex:1}.slot{position:relative;width:61px;height:61px;border:1px solid #e4e9dc;border-radius:12px;background:#fbfcf5;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:.15s;box-shadow:inset 0 -3px #f0f2e9}.slot:hover{transform:translateY(-2px);border-color:#b9d6b3}.slot.selected{border:2px solid #72b47b;background:#f1f8e9;box-shadow:0 3px 10px #66a86a20,inset 0 -3px #e1efda}.slot .item-emoji{font-size:26px;filter:drop-shadow(0 2px 0 #46542a28)}.slot .item-count{position:absolute;bottom:4px;right:6px;color:#68837b;font:500 9px 'DM Mono',monospace}.slot .slot-key{position:absolute;top:4px;left:6px;color:#b3beb1;font:9px 'DM Mono',monospace}.inventory-note{display:flex;align-items:center;gap:8px;color:#91a19a;font-size:9px;line-height:1.45;min-width:112px}.inventory-note b{color:#648477}.mouse-icon{font-size:21px;color:#78a58a}.plant-btn{height:43px;white-space:nowrap;border:0;border-radius:11px;padding:0 15px;background:#e6f4d9;color:#58875f;display:flex;align-items:center;gap:8px;font:800 9px 'DM Mono',monospace;letter-spacing:.4px;cursor:pointer;transition:.15s}.plant-btn:hover{background:#d7edc7;transform:translateY(-1px)}.plant-btn span{font-size:17px}.bottom-note{display:flex;align-items:center;padding:0 23px;height:34px;color:#9bada0;font-size:10px;background:#fbfcf5;border-top:1px solid #eff1e9}.bottom-note>span:first-child{color:#edbd59;margin-right:7px}.bottom-divider{margin:0 8px;color:#cbd3c7}.bottom-spacer{flex:1}#resetBtn{border:0;background:none;color:#91a89b;font:inherit;cursor:pointer}#resetBtn:hover{color:#558a68}.touch-controls{display:none;pointer-events:auto;position:absolute;left:16px;bottom:17px;gap:8px}.touch-controls button{width:46px;height:46px;border:1px solid #ffffff9c;background:#fffaf0c9;border-radius:13px;color:#567c69;font-size:24px;box-shadow:0 3px 12px #315a4b20;touch-action:none}.mobile-tip{display:none}dialog{border:0;border-radius:20px;max-width:430px;width:calc(100% - 32px);padding:27px;background:#fffdf7;color:var(--ink);box-shadow:0 20px 70px #29463a45}dialog::backdrop{background:#24483c77;backdrop-filter:blur(3px)}.dialog-head{display:flex;justify-content:space-between}.dialog-sparkle{display:grid;place-items:center;width:37px;height:37px;border-radius:12px;background:#fff0c9;color:#d79b42;font-size:21px}.close-btn{border:0;background:#f3f5ec;border-radius:9px;width:30px;height:30px;color:#7b9288;font-size:19px;cursor:pointer}dialog h2{margin:18px 0 7px;font-size:25px;letter-spacing:-.7px}dialog p{margin:0;color:#82948a;font-size:13px;line-height:1.55}.help-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:20px 0}.help-grid div{background:#f5f8ef;border-radius:12px;padding:12px;display:grid;grid-template-columns:27px 1fr;align-items:center}.help-grid div>span{grid-row:span 2;font-size:20px}.help-grid b{font-size:12px}.help-grid small{font-size:10px;color:#869990;line-height:1.35;margin-top:2px}.primary-btn{width:100%;height:44px;background:#70ad77;color:white;border:0;border-radius:11px;font:800 10px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.primary-btn:hover{background:#599766}
@media(max-width:700px){body{padding:0;background:#f5f8ee;display:block}.game-shell{width:100%;min-height:100dvh;border-radius:0;border:0;display:flex;flex-direction:column}.topbar{height:55px;padding:0 14px}.brand{font-size:17px}.brand-mark{width:27px;height:27px}.world-title{position:static;transform:none;margin-left:auto;margin-right:10px;font-size:8px;gap:5px}.top-actions{gap:5px}.icon-btn,.avatar-mini{width:30px;height:30px}.game-frame{height:calc(100dvh - 55px - 148px);min-height:330px;flex:1}.quest-card{left:10px;top:10px;min-width:0;padding:7px}.quest-card small{font-size:7px}.quest-card strong{font-size:10px}.quest-progress{font-size:8px}.world-badge{right:10px;top:10px;padding:6px 8px}.controls-hint{display:none}.touch-controls{display:flex}.inventory-bar{min-height:95px;gap:7px;padding:9px 9px;flex-wrap:wrap}.inventory-label{min-width:auto;font-size:7px;gap:5px}.bag-icon{height:29px;width:29px}.slots{gap:4px;justify-content:center}.slot{width:min(13vw,56px);height:min(13vw,56px);max-width:56px;max-height:56px;border-radius:10px}.slot .item-emoji{font-size:23px}.inventory-note{display:none}.plant-btn{height:38px;padding:0 9px;font-size:8px;gap:4px}.bottom-note{height:31px;padding:0 12px;font-size:9px}.bottom-note #resetBtn{font-size:9px}.mobile-tip{position:absolute;left:50%;bottom:113px;transform:translateX(-50%);background:#fffaf0db;padding:7px 10px;border-radius:9px;color:#6d8b7b;font-size:10px;white-space:nowrap;pointer-events:none;animation:fadeTip 5s forwards}.touch-controls{bottom:15px}.touch-controls button:last-child{margin-left:7px;background:#e5f3d9}.bottom-note .bottom-divider{margin:0 4px}}@media(max-width:390px){.world-title{letter-spacing:.4px}.top-actions .icon-btn:first-child{display:none}.inventory-label{display:none}.plant-btn{padding:0 7px}.slot{width:12.3vw;height:12.3vw}.world-badge small{display:none}}@keyframes fadeTip{0%,75%{opacity:1}100%{opacity:0}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const TILE = 32, WORLD_W = 80, WORLD_H = 30;
  const SAVE_KEY = 'sproutbound-save-v1';
  const blockDefs = {
    1:{name:'Grass',emoji:'🟩',color:'#83b967',hardness:1},
    2:{name:'Soft soil',emoji:'🟫',color:'#aa7955',hardness:1},
    3:{name:'Pebble stone',emoji:'🪨',color:'#8b9b9b',hardness:2},
    4:{name:'Sunwood',emoji:'🪵',color:'#bd8751',hardness:1},
    5:{name:'Leafy',emoji:'🍃',color:'#5d9c67',hardness:1},
    6:{name:'Daisy',emoji:'🌼',color:'#f8d870',hardness:1},
    7:{name:'Seed',emoji:'🌰',color:'#986b49',hardness:0}
  };
  let world, plants, inventory, selected = 0, player, cameraX = 0, cameraY = 0;
  let canvasW = 800, canvasH = 500, dpr = 1, last = performance.now(), saveTimer, toastTimer, particles = [], clouds = [];
  let keys = {}, touch = {left:false,right:false}, plantedCount = 0, questDone = false, soundOn = false;

  function blankWorld(){
    const arr = Array.from({length:WORLD_H},()=>Array(WORLD_W).fill(0));
    for(let x=0;x<WORLD_W;x++){
      const surface = Math.round(19 + Math.sin(x*.17)*1.15 + Math.sin(x*.047)*1.5 + (Math.random()-.5)*.8);
      for(let y=surface;y<WORLD_H;y++) arr[y][x] = y===surface ? 1 : y<surface+5 ? 2 : (Math.random()<.12 ? 3 : (y>surface+11 && Math.random()<.18 ? 3:2));
      // natural grass tufts and flower sprigs
      if(Math.random()<.24 && x>3 && x<WORLD_W-4) arr[surface-1][x]=6;
    }
    // little stone pockets
    for(let i=0;i<60;i++){let x=2+Math.random()*(WORLD_W-4)|0,y=22+Math.random()*7|0;if(arr[y]&&arr[y][x]===2)arr[y][x]=3;}
    // landmark trees
    for(const x of [10,23,39,57,70]) growTree(arr,x);
    return arr;
  }
  function growTree(arr,x){
    let ground=0;for(let y=0;y<WORLD_H;y++)if(arr[y][x]===1){ground=y;break;}
    for(let y=ground-1;y>ground-5;y--) if(y>=0) arr[y][x]=4;
    for(let yy=ground-8;yy<ground-3;yy++) for(let xx=x-2;xx<=x+2;xx++){
      if(yy>=0&&xx>=0&&xx<WORLD_W&&Math.abs(xx-x)+Math.abs(yy-(ground-6))<4&&arr[yy][xx]===0)arr[yy][xx]=5;
    }
    if(ground-7>=0&&arr[ground-7][x]===0)arr[ground-7][x]=5;
  }
  function freshGame(){
    world=blankWorld();plants={}; inventory=[{id:1,count:10},{id:2,count:12},{id:3,count:7},{id:4,count:8},{id:5,count:8},{id:7,count:5}];selected=0;
    let ground=0;for(let y=0;y<WORLD_H;y++)if(world[y][8]===1){ground=y;break;}
    player={x:8*TILE,y:(ground-2)*TILE,w:21,h:29,vx:0,vy:0,onGround:false,face:1,walk:0}; plantedCount=0;questDone=false;particles=[];save();
  }
  function load(){
    try{const data=JSON.parse(localStorage.getItem(SAVE_KEY));if(data&&data.world&&data.world.length===WORLD_H){world=data.world;plants=data.plants||{};inventory=data.inventory||[];selected=data.selected||0;player=data.player||{x:8*TILE,y:300,w:21,h:29,vx:0,vy:0,onGround:false,face:1,walk:0};plantedCount=data.plantedCount||0;questDone=data.questDone||false;return true;}}catch(e){}
    return false;
  }
  function save(){
    try{localStorage.setItem(SAVE_KEY,JSON.stringify({world,plants,inventory,selected,player,plantedCount,questDone}));document.getElementById('saveStatus').textContent='All changes saved';}catch(e){document.getElementById('saveStatus').textContent='Playing this session';}
  }
  function scheduleSave(){document.getElementById('saveStatus').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(save,500);}
  if(!load())freshGame();
  clouds=Array.from({length:8},(_,i)=>({x:i*210+Math.random()*100,y:25+Math.random()*125,s:.65+Math.random()*.8}));

  function resize(){
    const r=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);canvasW=r.width;canvasH=r.height;
    canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize',resize);resize();
  function solidAt(tx,ty){if(tx<0||tx>=WORLD_W||ty>=WORLD_H)return true;if(ty<0)return false;return world[ty][tx]!==0;}
  function intersectsSolid(x,y,w,h){const l=Math.floor(x/TILE),r=Math.floor((x+w-1)/TILE),t=Math.floor(y/TILE),b=Math.floor((y+h-1)/TILE);for(let yy=t;yy<=b;yy++)for(let xx=l;xx<=r;xx++)if(solidAt(xx,yy))return true;return false;}
  function movePlayer(dt){
    const left=keys.ArrowLeft||keys.KeyA||touch.left,right=keys.ArrowRight||keys.KeyD||touch.right;
    let dir=(right?1:0)-(left?1:0);player.vx=dir*205;if(dir){player.face=dir;player.walk+=dt*12;}
    player.vy=Math.min(player.vy+1500*dt,720);
    let nx=player.x+player.vx*dt;
    if(!intersectsSolid(nx,player.y,player.w,player.h))player.x=nx;else player.vx=0;
    let ny=player.y+player.vy*dt;
    if(!intersectsSolid(player.x,ny,player.w,player.h)){player.y=ny;player.onGround=false;}else{
      if(player.vy>0){player.y=Math.floor((player.y+player.h)/TILE)*TILE-player.h;player.onGround=true;}else player.y=Math.ceil(player.y/TILE)*TILE;
      player.vy=0;
    }
    player.x=Math.max(TILE,Math.min(WORLD_W*TILE-player.w-TILE,player.x));
  }
  function jump(){if(player.onGround){player.vy=-525;player.onGround=false;}}
  function centerCam(){cameraX=player.x+player.w/2-canvasW/2;cameraY=player.y+player.h/2-canvasH*.56;cameraX=Math.max(0,Math.min(WORLD_W*TILE-canvasW,cameraX));cameraY=Math.max(-120,Math.min(WORLD_H*TILE-canvasH,cameraY));}
  function drawBackground(time){
    const sky=ctx.createLinearGradient(0,0,0,canvasH);sky.addColorStop(0,'#83cfe4');sky.addColorStop(.64,'#c4e9dc');sky.addColorStop(1,'#e7ebc7');ctx.fillStyle=sky;ctx.fillRect(0,0,canvasW,canvasH);
    // sun halo
    ctx.fillStyle='#fff4c573';ctx.beginPath();ctx.arc(canvasW*.78,canvasH*.2,57,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff1b7';ctx.beginPath();ctx.arc(canvasW*.78,canvasH*.2,32,0,Math.PI*2);ctx.fill();
    clouds.forEach(c=>{let x=(c.x-time*.008)%(canvasW+210);if(x< -100)x+=canvasW+210;drawCloud(x,c.y,c.s);});
    ctx.fillStyle='#95ceae';ctx.beginPath();ctx.moveTo(0,canvasH*.64);for(let x=0;x<=canvasW+20;x+=20)ctx.lineTo(x,canvasH*.61+Math.sin((x+cameraX*.12)*.005)*18+Math.sin(x*.012)*7);ctx.lineTo(canvasW,canvasH);ctx.lineTo(0,canvasH);ctx.fill();
    ctx.fillStyle='#a7d8aa';ctx.beginPath();ctx.moveTo(0,canvasH*.75);for(let x=0;x<=canvasW+20;x+=20)ctx.lineTo(x,canvasH*.73+Math.sin((x+cameraX*.22)*.007)*13);ctx.lineTo(canvasW,canvasH);ctx.lineTo(0,canvasH);ctx.fill();
  }
  function drawCloud(x,y,s){ctx.fillStyle='#f7ffefb0';ctx.beginPath();ctx.ellipse(x,y,34*s,11*s,0,0,Math.PI*2);ctx.ellipse(x-17*s,y-7*s,17*s,13*s,0,0,Math.PI*2);ctx.ellipse(x+3*s,y-12*s,22*s,17*s,0,0,Math.PI*2);ctx.ellipse(x+22*s,y-4*s,17*s,11*s,0,0,Math.PI*2);ctx.fill();}
  function drawTile(id,x,y,tx,ty){
    const px=x*TILE-cameraX,py=y*TILE-cameraY;
    if(id===1){ctx.fillStyle='#8c654d';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#80b965';ctx.fillRect(px,py,TILE,8);ctx.fillStyle='#a2d17a';ctx.fillRect(px,py,TILE,3);ctx.fillStyle='#6b9f59';ctx.fillRect(px,py+7,TILE,2);}
    else if(id===2){ctx.fillStyle='#a97853';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#bd906a';ctx.fillRect(px+3,py+7,5,3);ctx.fillRect(px+20,py+18,7,3);ctx.fillStyle='#90664b';ctx.fillRect(px+12,py+25,4,3);}
    else if(id===3){ctx.fillStyle='#829493';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#a9b5aa';ctx.fillRect(px+4,py+5,9,4);ctx.fillRect(px+19,py+18,8,4);ctx.fillStyle='#687c7d';ctx.fillRect(px+5,py+21,6,3);ctx.fillRect(px+22,py+8,4,3);}
    else if(id===4){ctx.fillStyle='#986744';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#c48d56';ctx.fillRect(px+7,py,4,TILE);ctx.fillStyle='#7d553e';ctx.fillRect(px+22,py,3,TILE);}
    else if(id===5){ctx.fillStyle='#5e9d66';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#78b779';ctx.fillRect(px+4,py+3,11,8);ctx.fillRect(px+18,py+17,10,9);ctx.fillStyle='#4b875b';ctx.fillRect(px+16,py+4,8,7);}
    else if(id===6){ctx.fillStyle='#80b965';ctx.fillRect(px,py,TILE,8);ctx.fillStyle='#f6d76f';ctx.fillRect(px+14,py-5,4,5);ctx.fillStyle='#5d9d66';ctx.fillRect(px+15,py-10,2,7);ctx.fillStyle='#fff2ca';ctx.fillRect(px+12,py-16,6,6);ctx.fillRect(px+8,py-12,5,6);ctx.fillRect(px+17,py-12,5,6);ctx.fillStyle='#e7b952';ctx.fillRect(px+13,py-12,5,5);}
    // subtle block seams
    if(id!==6){ctx.strokeStyle='#344f4320';ctx.lineWidth=1;ctx.strokeRect(px+.5,py+.5,TILE-1,TILE-1);}
  }
  function drawPlant(key,p,time){const [tx,ty]=key.split(',').map(Number),px=tx*TILE-cameraX,py=ty*TILE-cameraY;const age=(Date.now()-p.time);const stage=Math.min(3,Math.floor(age/18000));const stem=8+stage*5;ctx.fillStyle='#4b915d';ctx.fillRect(px+15,py-stem,3,stem);ctx.fillStyle='#73b56e';if(stage>0){ctx.fillRect(px+8,py-stem+5,8,4);ctx.fillRect(px+17,py-stem+10,7,4);}if(stage>=2){ctx.fillStyle='#fff2c6';ctx.fillRect(px+11,py-stem-7,10,9);ctx.fillStyle=stage>=3?'#e7a743':'#f2d66b';ctx.fillRect(px+14,py-stem-4,5,5);}if(stage>=3){ctx.fillStyle='#edbd62';ctx.beginPath();ctx.arc(px+22,py-stem+9,3,0,Math.PI*2);ctx.fill();}p.stage=stage;}
  function drawPlayer(){
    const x=Math.round(player.x-cameraX),y=Math.round(player.y-cameraY),walk=Math.sin(player.walk)*2.5;
    // shadow
    ctx.fillStyle='#416c5640';ctx.beginPath();ctx.ellipse(x+player.w/2,y+player.h+2,14,4,0,0,Math.PI*2);ctx.fill();
    ctx.save();if(player.face<0){ctx.translate(x+player.w,0);ctx.scale(-1,1);ctx.translate(-x,0);}
    // legs
    ctx.fillStyle='#597b69';ctx.fillRect(x+4,y+20+Math.max(0,walk),6,9-Math.max(0,walk));ctx.fillRect(x+12,y+20+Math.max(0,-walk),6,9-Math.max(0,-walk));ctx.fillStyle='#e4a96b';ctx.fillRect(x+3,y+27,8,3);ctx.fillRect(x+11,y+27,8,3);
    // body
    ctx.fillStyle='#f4bf79';ctx.fillRect(x+3,y+10,16,12);ctx.fillStyle='#edaa68';ctx.fillRect(x+4,y+18,14,4);ctx.fillStyle='#fff4dd';ctx.fillRect(x+4,y+12,14,6);
    // head and hair cap
    ctx.fillStyle='#f4c38b';ctx.fillRect(x+4,y+1,14,12);ctx.fillStyle='#764d3d';ctx.fillRect(x+3,y,15,5);ctx.fillRect(x+2,y+3,4,6);ctx.fillRect(x+14,y+3,4,3);
