    const sx=Math.max(0,Math.floor(cameraX/TILE)-1),ex=Math.min(WORLD_W,Math.ceil((cameraX+canvasW)/TILE)+1),sy=Math.max(0,Math.floor(cameraY/TILE)-1),ey=Math.min(WORLD_H,Math.ceil((cameraY+canvasH)/TILE)+1);
